import{_ as i,l as n,o as a,c as l,v as t,p as s,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"密码学误用清单","description":"","frontmatter":{"title":"密码学误用清单","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/crypto-misuse.md","filePath":"cs/crypto-misuse.md","lastUpdated":1789023840000}'),E={name:"cs/crypto-misuse.md"};function A(h,e,u,m,_,C){const o=n("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="密码学误用清单" tabindex="-1">密码学误用清单 <a class="header-anchor" href="#密码学误用清单" aria-label="Permalink to &quot;密码学误用清单&quot;">​</a></h1><div class="epigraph"><p>破掉产品的常常不是新的密码分析，而是 ECB、nonce 复用、裸哈希当 MAC、自制 RNG、把身份写进 JWT 却不验签。清单用来对照合同，不是利用手册。</p><footer>—— 据 Anderson, *Security Engineering*；Egele et al. 对 Android 密码学误用的测量；对照 NIST 与 RFC 的合同条款</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/provable-security-reduction">归约</a>说明证明有前提。缺口是把本单元散见的失败收成<strong>检查单</strong>，作为密码学进阶的封口，并交给下一单元「证书链到底验什么」。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>工程上重复出现：ECB 或未认证加密、静态 IV、CBC+可区分填充错误、\\(H(k\\|m)\\)、MD5 当签名哈希、RSA 无填充、ECDSA 坏 \\(k\\)、硬编码密钥、自签还关校验。缺口是清单与「每条对应哪一课合同」，不是新算法。</p><h3 id="库默认值也是合同" tabindex="-1">库默认值也是合同 <a class="header-anchor" href="#库默认值也是合同" aria-label="Permalink to &quot;库默认值也是合同&quot;">​</a></h3><p>有的 API 默认 ECB 或允许 <code>None</code> 算法。选库等于选游戏前提。</p><p><span class="marginnote">Anderson 反复强调实现与流程。学术测量（如 CryptoLint 一类）表明误用普遍。本课不提供扫描目标站点的操作指南。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按原语课序对照列出「正确形状」。要求：AEAD、唯一 nonce、HMAC/HKDF、OAEP/PSS、CSPRNG、密钥分离、常数时间比较。指出下一单元从 PKI 验证细节开始，因为「有证书」仍可能什么都没验。</p>',12)),(a(),s(p,null,{default:r(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E9%80%89%E9%94%99%E6%A8%A1%E5%BC%8F%2Fnonce%22%5D%20--%3E%20FAIL%5B%22%E6%B8%B8%E6%88%8F%E5%89%8D%E6%8F%90%E7%A0%B4%22%5D%0A%20%20L2%5B%22%E8%A3%B8%E5%93%88%E5%B8%8C%E5%BD%93%E8%AE%A4%E8%AF%81%22%5D%20--%3E%20FAIL%0A%20%20L3%5B%22%E5%9D%8F%20RNG%20%2F%20%E5%AF%86%E9%92%A5%E7%A1%AC%E7%BC%96%E7%A0%81%22%5D%20--%3E%20FAIL%0A%20%20FAIL%20--%3E%20FIX%5B%22%E5%9B%9E%E5%88%B0%20AEAD%20%E4%B8%8E%20HKDF%20%E5%90%88%E5%90%8C%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>误用把可证明对象变回「有加密外观」。审查应问合同而非算法名。协议与身份单元将看到：TLS 配置、JWT <code>alg</code>、OAuth 重定向，是同一类失败在协议层的投影。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把清单写成攻击脚本。下一课程单元「协议与身份」第一课：证书链验证细节——主干 PKI 课之后仍被跳过的那些检查。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>归约在合同内；本课列合同外高频失败。</li><li>AEAD、nonce、HMAC、填充、RNG、密钥分离。</li><li>库默认与「有加密」不是证明。</li><li>下一单元：证书链验证细节。</li><li>出处：Anderson, <em>Security Engineering</em>；Egele et al.；NIST SP 800-38 系列与 RFC 8446。</li></ul>',8))])}const P=i(E,[["render",A]]);export{f as __pageData,P as default};
